class Solution {
public:
    int maxDepth(string s) {
        int curr_depth = 0, max_depth = 0;
        for (char ch : s) {
            if (ch == '(') {
                curr_depth++;
                max_depth = max(max_depth, curr_depth);
            } else if (ch == ')') {
                curr_depth--;
            }
        }
        return max_depth;
    }
};

class Solution {
    public int maxDepth(String s) {
        int currDepth = 0, maxDepth = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                currDepth++;
                maxDepth = Math.max(maxDepth, currDepth);
            } else if (ch == ')') {
                currDepth--;
            }
        }
        return maxDepth;
    }
}

var maxDepth = function(s) {
    let currDepth = 0;
    let maxDepth = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') {
            currDepth++;
            maxDepth = Math.max(maxDepth, currDepth);
        } else if (s[i] === ')') {
            currDepth--;
        }
    }
    return maxDepth;
};
